queries.query:
find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate { distinct_count(d.stage_execution_id) as deployments }

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate { distinct_count(d.service_identifier) as services }

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| filter d.env_identifier != ""
| aggregate { distinct_count(d.env_identifier) as environments }

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate { count(case when d.stage_status in ["FAILED", "ABORTED", "EXPIRED", "APPROVAL_REJECTED", "APPROVALREJECTED", "ERRORED"] then 1 end) as failed_deployments }

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate {
    d.service_name as service,
    case when d.env_name = "" then "Unassigned" else d.env_name end as environment,
    distinct_count(d.stage_execution_id) as deployments
  }
| group_by service, environment
| order_by deployments desc

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate {
    case when d.env_type = "" then "Unclassified" else d.env_type end as env_type,
    distinct_count(d.stage_execution_id) as deployments
  }
| group_by env_type
| order_by deployments desc

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate {
    date_trunc("day", d.start_ts) as day,
    case when d.env_name = "" then "Unassigned" else d.env_name end as environment,
    distinct_count(d.stage_execution_id) as deployments
  }
| group_by day, environment
| order_by day asc

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| filter d.stage_duration > 0
| aggregate {
    date_trunc("week", d.start_ts) as week,
    d.service_name as service,
    avg(d.stage_duration) / 1000.0 as avg_duration_s
  }
| group_by week, service
| order_by week asc

find view "cd:active_instances" a
| join view "cd:deployment_stage_execution" d on d.service_identifier = a.serviceid and d.project_identifier = a.projectid
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate {
    d.service_name as service,
    case when d.env_name = "" then "Unassigned" else d.env_name end as environment,
    distinct_count(a.unique_id) as instances
  }
| group_by service, environment
| order_by instances desc

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate {
    case when d.deployment_type = "" then "Unknown" else d.deployment_type end as deployment_type,
    distinct_count(d.stage_execution_id) as deployments
  }
| group_by deployment_type
| order_by deployments desc

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate { d.execution_strategy_type as strategy, distinct_count(d.stage_execution_id) as deployments }
| group_by strategy
| order_by deployments desc
